SELECT product_id, CASE WHEN quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, CORR(quantity, unit_price) AS corr_quantity_unit_price, ROUND(AVG(unit_price), 2) AS avg_unit_price, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY ROUND(AVG(unit_price), 2) DESC) AS avg_unit_price_percent_rank FROM order_items GROUP BY 1, 2 ORDER BY product_id DESC NULLS LAST
